  /* ── A-grp-audit 감사 · 역할 ── */
  const ACTN = { 'dash.view': '통합 현황 조회', 'dash.export': '집계 내려받기', 'learner.lookup': '학습자 개별 열람', 'learner.summary': '통합 학습자 집계 조회', 'share.publish': '콘텐츠 배포', 'share.create': '배포 초안', 'share.version': '새 버전 배포', 'share.recall': '콘텐츠 회수', 'invite.create': '초대 코드 발급', 'invite.cancel': '초대 취소', 'link.remove': '연결 해제', 'policy.set': '공통 설정 편집', 'policy.apply': '공통 설정 일괄 적용', 'staff.set': '역할 지정', 'rules.set': '경고 기준 변경', 'group.update': '목표값 변경', 'request.approve': '공유 요청 승인', 'request.reject': '공유 요청 반려', 'learner.view': '학습자 개별 열람', staff: '역할 지정' };
